    // Base case: if n is 1, return 0
    if (n == 1) {
        return 0;
    }

    // Recursive case: if n is even, get the binary log of half the value
    if (n % 2 == 0) {
        return computeBinaryLog(n / 2) + 1;
    }

    // Recursive case: if n is odd, get the binary log of half the value
    else {
