    // Loop through all pairs of vertices in the subgraph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            // If the subgraph is not a complete graph, return false
            if (v1 == v2) continue;
            if (!graph.getEdge(v1, v2).isPresent()) return false;
        }
    }

    // If the subgraph is a complete graph, return true
    return true;
