    // Check if the subgraph induced by the given vertices is a clique
    for (V vertex : vertices) {
        // Check if the vertex is connected to all other vertices in the subgraph
        for (V otherVertex : vertices) {
            if (!graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // If the set of vertices is empty, return true (there is no vertex to connect)
    if (vertices.isEmpty()) {
        return true;
    }

    // If there is only one vertex, return true (there is no edge to check)
    if (vertices.size() == 1) {
        return true;
    }

    // Iterate over all pairs of vertices and check if there is an edge connecting them
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.hasEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    // If all pairs of vertices have an edge, return true
    return true;
}

public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the input graph and set of vertices are valid
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph and set of vertices must be non-null and non-empty");
    }

    // Create a new set to store the neighbor vertices of each vertex in the subgraph
    Set<V> neighborVertices = new HashSet<>();

    // Iterate over each vertex in the subgraph
    for (V vertex : vertices) {
        // Get the neighbor vertices of the current vertex
        neighborVertices.addAll(graph.getNeighbors(vertex));
    }

    // Return true if the subgraph is a clique, i.e. the intersection of the neighbor vertices and the subgraph vertices is the same as the subgraph vertices
    return vertices.size() == neighborVertices.size() && neighborVertices.containsAll(vertices);
}

