public String unescapeId(String input) {
    int index;
    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c != '.') {
            sb.append(c);
        }
        else {
            index = i + 1;
            if (index < input.length() && input.charAt(index) == '\\') {
                index++;
            }
            if (index < input.length() && input.charAt(index) == '.') {
                i = index;
            }
            else {
                throw new IllegalArgumentException("Invalid dot escape");
            }
        }
    }

