public static String applyRelativePath(String path, String relativePath) {
	StringBuilder result = new StringBuilder();
	String[] pathElements = path.split("/");
	relativePath = relativePath.replace("\\", "/");
	String[] relativePathElements = relativePath.split("/");
	for (int i = 0; i < relativePathElements.length; i++) {
		if (relativePathElements[i].equals("..")) {
			if (pathElements.length > 0) {
				pathElements = Arrays.copyOfRange(pathElements, 0, pathElements.length - 1);
			}
		} else if (!relativePathElements[i].equals(".")) {
			pathElements = Arrays.copyOf(pathElements, pathElements.length + 1);
			pathElements[pathElements.length - 1] = relativePathElements[i];
		}
	}
	for (String element : pathElements) {
