			result.append("/");
		}
	}
	return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Split the given path and relative path into their respective path components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Create a new path string builder
    StringBuilder newPath = new StringBuilder();

    // Iterate over the path components and add them to the new path, skipping the first component if it is an empty string
    for (int i = 0; i < pathComponents.length; i++) {
      if (i == 0 && pathComponents[i].isEmpty()) {
        continue;
      }
      newPath.append(pathComponents[i]).append("/");
    }

    // Iterate over the relative path components and add them to the new path
    for (int i = 0; i < relativePathComponents.length; i++) {
      newPath.append(relativePathComponents[i]).append("/");
    }

    // Return the result of the path concatenation
    return newPath.toString();
  }

public String applyRelativePath(String path, String relativePath) {
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");
    String[] combinedPathComponents = new String[pathComponents.length + relativePathComponents.length];
    System.arraycopy(pathComponents, 0, combinedPathComponents, 0, pathComponents.length);
    System.arraycopy(relativePathComponents, 0, combinedPathComponents, pathComponents.length, relativePathComponents.length);
    return String.join("/", combinedPathComponents);
}

