public static void deleteFile(String fileName) {

    if (fileName == null) {
	    throw new NullPointerException("The provided file path is null");
    }

    File file = new File(fileName);

    if (!file.exists()) {
        System.out.println(fileName + " does not exist");
        return;
    }

    if (file.isDirectory()) {
        System.out.println(fileName + " is a directory");
        return;
    } else if (!file.isFile()) {
        System.out.println(fileName + " is not a regular file");
        return;
    }

    if (!file.canWrite()) {
        System.out.println("Cannot delete file: The file " + fileName + " cannot be written");
        return;
    }

    if (!file.delete()) {
        System.out.println("Cannot delete file: An error occurred while deleting the file " + fileName);
        return;
    }

    System.out.println("File " + fileName + " was successfully deleted");
}

protected static void deleteFile(String fileName) throws IOException {
        File file = new File(fileName);
        if (!file.exists()) {
            return;
        }
        if (!file.isFile()) {
            throw new IOException(fileName + " is not a valid file path");
        }
        if (!file.canWrite()) {
            throw new IOException(fileName + " is not writeable.");
        }
        file.delete();
    }

