public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Initialize an empty list to store the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Use a buffered reader to read the file line by line
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // If the line contains the start time of a new thread snapshot, create a new ThreadSnapshot object
            if (line.startsWith("--")) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot();
                threadSnapshot.setStartTime(Long.valueOf(line.split(" ")[1]));
                threadSnapshots.add(threadSnapshot);
            }
            // If the line contains the end time of a thread snapshot, set the end time for the current thread snapshot
            else if (line.startsWith("++")) {
                ThreadSnapshot threadSnapshot = threadSnapshots.get(threadSnapshots.size() - 1);
                threadSnapshot.setEndTime(Long.valueOf(line.split(" ")[1]));
            }
            // If the line contains a timestamp and a method name, add a method stack trace to the current thread snapshot
            else if (line.contains(".()")) {
                ThreadSnapshot threadSnapshot = threadSnapshots.get(threadSnapshots.size() - 1);
                String[] tokens = line.split(" ");
                long timestamp = Long.valueOf(tokens[0]);
                String methodName = tokens[2].substring(0, tokens[2].length() - 1);
                StackTraceElement stackTraceElement = new StackTraceElement(methodName, "", "", timestamp);
                threadSnapshot.getMethodStackTraces().add(stackTraceElement);
            }
        }
    }
    // Filter the thread snapshots to only include those within the specified time ranges
    threadSnapshots.stream()
        .filter(threadSnapshot -> timeRanges.stream()
            .anyMatch(timeRange -> threadSnapshot.getStartTime() >= timeRange.getStartTime() && threadSnapshot.getEndTime() <= timeRange.getEndTime()))
        .collect(Collectors.toList());
